public class PrivilegedCommandTimeoutBoundTest {

    private static final int TIMEOUT_SECONDS = 2;
    private static final long GRACE_MILLIS = 1000L;
    private static final long LONG_GRACE_MILLIS = 10000L;
    private static final long OUTPUT_DRAIN_MILLIS = 1000L;
    private static final long BOUND_MARGIN_MILLIS = 1500L;
    private static final long FAST_EXIT_MILLIS = 1500L;
    private static final long PROCESS_EXIT_WAIT_MILLIS = 3000L;
    private static final long LEADER_RUN_MILLIS = 1000L;

    private final List<Long> startedPids = new ArrayList<>();
    private ExecutorUtil executorUtil;
    private Path workDir;
    private Path pidFile;
    private Path markerFile;
    private Command command;
    private ByteArrayOutputStream output;
    private CommandStatus status;
    private long elapsedMillis;

    @Before
    public void setUp() throws IOException {
        Assume.assumeTrue(System.getProperty("os.name").toLowerCase(Locale.ROOT).contains("linux"));
        Assume.assumeTrue(new ExecutorUtil().getProcessGroupLauncher().isPresent());
        this.workDir = Files.createTempDirectory("kura-executor-bound");
        this.pidFile = this.workDir.resolve("pid");
        this.markerFile = this.workDir.resolve("marker");
    }

    @After
    public void tearDown() throws IOException {
        this.startedPids.forEach(pid -> ProcessHandle.of(pid).ifPresent(ProcessHandle::destroyForcibly));
        if (this.workDir != null) {
            Files.deleteIfExists(this.pidFile);
            Files.deleteIfExists(this.markerFile);
            Files.deleteIfExists(this.workDir);
        }
    }

    @Test
    public void backgroundChildOfShellCommandIsKilledOnTimeout() {
        givenExecutorWithGrace(GRACE_MILLIS);
        givenShellCommand("sleep 300 & echo $! > " + this.pidFile + "; wait");
        givenTimeout(TIMEOUT_SECONDS);

        whenExecutedSync();

        thenCallReturnedWithin(TIMEOUT_SECONDS * 1000L + GRACE_MILLIS + BOUND_MARGIN_MILLIS);
        thenTimedOutIs(true);
        thenRecordedProcessIsNotRunning();
    }

    @Test
    public void processIgnoringSigtermIsKilledAfterGrace() {
        givenExecutorWithGrace(GRACE_MILLIS);
        givenShellCommand("trap '' TERM; echo $$ > " + this.pidFile + "; while true; do sleep 1; done");
        givenTimeout(TIMEOUT_SECONDS);

        whenExecutedSync();

        thenCallReturnedAfter(TIMEOUT_SECONDS * 1000L);
        thenCallReturnedWithin(TIMEOUT_SECONDS * 1000L + GRACE_MILLIS + BOUND_MARGIN_MILLIS);
        thenTimedOutIs(true);
        thenRecordedProcessIsNotRunning();
    }

    @Test
    public void descendantHoldingOutputPipeIsKilledAtTimeout() {
        givenExecutorWithGrace(GRACE_MILLIS);
        givenShellCommand("sleep 300 & echo $! > " + this.pidFile + "; sleep 1");
        givenTimeout(TIMEOUT_SECONDS);

        whenExecutedSync();

        thenCallReturnedWithin(TIMEOUT_SECONDS * 1000L + GRACE_MILLIS + BOUND_MARGIN_MILLIS);
        thenTimedOutIs(true);
        thenRecordedProcessIsNotRunning();
    }

    @Test
    public void asyncCallbackIsBoundedWhenDescendantHoldsOutputPipe() {
        givenExecutorWithGrace(GRACE_MILLIS);
        givenShellCommand("sleep 300 & echo $! > " + this.pidFile + "; sleep 1");
        givenTimeout(TIMEOUT_SECONDS);

        whenExecutedAsync(TIMEOUT_SECONDS * 1000L + GRACE_MILLIS + BOUND_MARGIN_MILLIS);

        thenCallReturnedWithin(TIMEOUT_SECONDS * 1000L + GRACE_MILLIS + BOUND_MARGIN_MILLIS);
        thenTimedOutIs(true);
        thenRecordedProcessIsNotRunning();
    }

    @Test
    public void commandSignalIsSentToTheWholeGroup() {
        givenExecutorWithGrace(GRACE_MILLIS);
        givenShellCommand("(trap 'echo hangup > " + this.markerFile + "; exit 0' HUP; while true; do sleep 1; done) & echo $! > "
                + this.pidFile + "; wait");
        givenTimeout(TIMEOUT_SECONDS);
        givenSignal(LinuxSignal.SIGHUP);

        whenExecutedSync();

        thenTimedOutIs(true);
        thenMarkerFileContains("hangup");
        thenRecordedProcessIsNotRunning();
    }

    @Test
    public void killSignalStopsTheGroupWithoutGrace() {
        givenExecutorWithGrace(LONG_GRACE_MILLIS);
        givenShellCommand("trap '' TERM; echo $$ > " + this.pidFile + "; while true; do sleep 1; done");
        givenTimeout(TIMEOUT_SECONDS);
        givenSignal(LinuxSignal.SIGKILL);

        whenExecutedSync();

        thenCallReturnedWithin(TIMEOUT_SECONDS * 1000L + BOUND_MARGIN_MILLIS);
        thenTimedOutIs(true);
        thenRecordedProcessIsNotRunning();
    }

    @Test
    public void backgroundChildWithRedirectedOutputSurvivesNormalExit() {
        givenExecutorWithGrace(GRACE_MILLIS);
        givenShellCommand("sleep 30 > /dev/null 2>&1 & echo $! > " + this.pidFile);
        givenTimeout(TIMEOUT_SECONDS);

        whenExecutedSync();

        thenCallReturnedWithin(FAST_EXIT_MILLIS);
        thenTimedOutIs(false);
        thenExitCodeIs(0);
        thenRecordedProcessIsRunning();
    }

    @Test
    public void unboundedCommandStopsWaitingForHeldOutput() {
        givenExecutorWithGrace(GRACE_MILLIS);
        givenShellCommand("echo started; sleep 30 & echo $! > " + this.pidFile + "; sleep 1");
        givenOutputStream();

        whenExecutedSync();

        thenCallReturnedWithin(LEADER_RUN_MILLIS + OUTPUT_DRAIN_MILLIS + BOUND_MARGIN_MILLIS);
        thenTimedOutIs(false);
        thenOutputIncompleteIs(true);
        thenOutputContains("started");
        thenRecordedProcessIsRunning();
    }

    private void givenExecutorWithGrace(long graceMillis) {
        this.executorUtil = new ExecutorUtil("kura", graceMillis, OUTPUT_DRAIN_MILLIS) {
        };
    }

    private void givenShellCommand(String script) {
        this.command = new Command(new String[] { script });
        this.command.setExecuteInAShell(true);
        this.command.setSignal(LinuxSignal.SIGTERM);
    }

    private void givenTimeout(int seconds) {
        this.command.setTimeout(seconds);
    }

    private void givenSignal(Signal signal) {
        this.command.setSignal(signal);
    }

    private void givenOutputStream() {
        this.output = new ByteArrayOutputStream();
        this.command.setOutputStream(this.output);
    }

    private void whenExecutedSync() {
        final long start = System.nanoTime();
        this.status = this.executorUtil.executePrivileged(this.command);
        this.elapsedMillis = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start);
        recordStartedPid();
    }

    private void whenExecutedAsync(long maxWaitMillis) {
        final CountDownLatch done = new CountDownLatch(1);
        final AtomicReference<CommandStatus> result = new AtomicReference<>();
        final long start = System.nanoTime();
        this.executorUtil.executePrivileged(this.command, commandStatus -> {
            result.set(commandStatus);
            done.countDown();
        });
        try {
            assertTrue("The callback was not called within " + maxWaitMillis + " ms",
                    done.await(maxWaitMillis + BOUND_MARGIN_MILLIS, TimeUnit.MILLISECONDS));
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            fail("Interrupted while waiting for the callback");
        }
        this.elapsedMillis = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start);
        this.status = result.get();
        recordStartedPid();
    }

    private void recordStartedPid() {
        try {
            final String content = new String(Files.readAllBytes(this.pidFile), UTF_8).trim();
            this.startedPids.add(Long.parseLong(content));
        } catch (IOException | NumberFormatException e) {
            fail("The command did not record its pid: " + e.getMessage());
        }
    }

    private void thenCallReturnedWithin(long maxMillis) {
        assertTrue("The call took " + this.elapsedMillis + " ms, expected at most " + maxMillis + " ms",
                this.elapsedMillis <= maxMillis);
    }

    private void thenCallReturnedAfter(long minMillis) {
        assertTrue("The call took " + this.elapsedMillis + " ms, expected at least " + minMillis + " ms",
                this.elapsedMillis >= minMillis);
    }

    private void thenTimedOutIs(boolean expected) {
        assertEquals(expected, this.status.isTimedout());
    }

    private void thenExitCodeIs(int expected) {
        assertEquals(expected, this.status.getExitStatus().getExitCode());
    }

    private void thenOutputIncompleteIs(boolean expected) {
        assertEquals(expected, this.status.isOutputIncomplete());
    }

    private void thenOutputContains(String expected) {
        assertTrue(new String(this.output.toByteArray(), UTF_8).contains(expected));
    }

    private void thenMarkerFileContains(String expected) {
        final long deadline = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(PROCESS_EXIT_WAIT_MILLIS);
        String content = "";
        while (System.nanoTime() < deadline) {
            try {
                if (Files.exists(this.markerFile)) {
                    content = new String(Files.readAllBytes(this.markerFile), UTF_8);
                    if (content.contains(expected)) {
                        return;
                    }
                }
                Thread.sleep(50);
            } catch (IOException e) {
                fail("Cannot read the marker file: " + e.getMessage());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                fail("Interrupted while waiting for the marker file");
            }
        }
        fail("The marker file does not contain '" + expected + "': '" + content + "'");
    }

    private void thenRecordedProcessIsNotRunning() {
        final long pid = this.startedPids.get(this.startedPids.size() - 1);
        final long deadline = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(PROCESS_EXIT_WAIT_MILLIS);
        while (isRunning(pid) && System.nanoTime() < deadline) {
            try {
                Thread.sleep(50);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                fail("Interrupted while waiting for process " + pid + " to exit");
            }
        }
        assertFalse("Process " + pid + " is still running", isRunning(pid));
    }

    private void thenRecordedProcessIsRunning() {
        final long pid = this.startedPids.get(this.startedPids.size() - 1);
        assertTrue("Process " + pid + " is not running", isRunning(pid));
    }

    private static boolean isRunning(long pid) {
        try {
            final List<String> stat = Files.readAllLines(Path.of("/proc", Long.toString(pid), "stat"), UTF_8);
            if (stat.isEmpty()) {
                return false;
            }
            final String line = stat.get(0);
            final String state = line.substring(line.lastIndexOf(')') + 2, line.lastIndexOf(')') + 3);
            return !"Z".equals(state) && !"X".equals(state);
        } catch (IOException e) {
            return false;
        }
    }
}
